#!/usr/bin/env python3
from __future__ import annotations

import ast
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TASK = ROOT / "jetstream-regional-stream-continuity"


def replace_node(path: Path, name: str, replacement: str) -> None:
    text = path.read_text(encoding="utf-8")
    tree = ast.parse(text)
    matches = [
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == name
    ]
    if len(matches) != 1:
        raise RuntimeError(f"{path}: expected one {name}, found {len(matches)}")
    node = matches[0]
    source = text.splitlines(keepends=True)
    source[node.lineno - 1 : node.end_lineno] = [replacement.rstrip() + "\n"]
    path.write_text("".join(source), encoding="utf-8")


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{path}: expected one anchor, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


tests = TASK / "tests/test_continuity.py"
coverage = TASK / "tests/test_contract_coverage.py"
solution = TASK / "solution/files/engine.py"

replace_node(tests, 'test_f2p_retry_uses_stable_event_id', 'def test_f2p_retry_uses_stable_event_id(\n    engine: ContinuityEngine, tmp_path: Path\n) -> None:\n    """Physical replay preserves the complete stable origin identity and message headers."""\n    runtime_root = tmp_path / "stable-replay-identity"\n    nats_config_dir = runtime_root / "config/nats"\n    west_store = runtime_root / "state/nats/west"\n    nats_config_dir.mkdir(parents=True)\n    west_store.mkdir(parents=True)\n    (nats_config_dir / "west.conf").write_text(\n        "\\n".join(\n            (\n                "server_name: EDGE-WEST-F2P-IDENTITY",\n                "port: 4224",\n                "http: 8224",\n                "jetstream {",\n                f\'  store_dir: "{west_store}"\',\n                \'  domain: "edge-west"\',\n                "  max_mem_store: 67108864",\n                "  max_file_store: 268435456",\n                "}",\n                "",\n            )\n        ),\n        encoding="utf-8",\n    )\n\n    expected_stream = str(engine.store.region("west")["physical_stream"])\n    expected_replay_ids = {\n        item.event_id\n        for item in engine.store.replay_items("rp-west-incident-001")\n        if engine.store.archive_record(item.event_id) is None\n    }\n    expected_events = {\n        event_id: engine.store.event_by_id(event_id)\n        for event_id in expected_replay_ids\n    }\n    assert expected_replay_ids\n    assert all(event is not None for event in expected_events.values())\n\n    manager = LabProcessManager(runtime_root)\n    manager.start_one("west")\n    try:\n        manager.wait_monitor("http://127.0.0.1:8224", timeout=10)\n        lease = engine.acquire_recovery_lease(\n            region="west",\n            owner_id="f2p-stable-identity-worker",\n            ttl_seconds=300,\n            at=datetime.now(UTC),\n        )\n\n        async def publish_and_observe() -> tuple[object, list[object]]:\n            pool = NatsConnectionPool()\n            try:\n                endpoints = endpoints_from_engine(engine)\n                admin = JetStreamAdmin(pool, endpoints)\n                await admin.upsert_stream(\n                    "west",\n                    expected_stream,\n                    {\n                        "subjects": ["telemetry.west.>"],\n                        "retention": "limits",\n                        "storage": "file",\n                        "num_replicas": 1,\n                        "duplicate_window": 120 * 1_000_000_000,\n                        "max_age": 259200 * 1_000_000_000,\n                        "allow_direct": False,\n                        "deny_delete": True,\n                        "deny_purge": True,\n                    },\n                )\n                outcome = await engine.execute_replay_plan(\n                    "rp-west-incident-001",\n                    owner_id="f2p-stable-identity-worker",\n                    fence_epoch=lease.fence_epoch,\n                    publisher=NatsPublisher(pool, endpoints["west"]),\n                )\n                snapshot = await admin.stream_info("west", expected_stream)\n                messages = [\n                    await admin.get_message_by_sequence(\n                        "west", expected_stream, sequence\n                    )\n                    for sequence in range(\n                        snapshot.first_sequence, snapshot.last_sequence + 1\n                    )\n                ]\n                return outcome, messages\n            finally:\n                await pool.close()\n\n        outcome, messages = asyncio.run(publish_and_observe())\n        assert outcome.completed is True\n        observed: set[str] = set()\n        for message in messages:\n            document = json.loads(message.data.decode("utf-8"))\n            event_id = str(document["event_id"])\n            if event_id not in expected_replay_ids:\n                continue\n            event = expected_events[event_id]\n            assert event is not None\n            observed.add(event_id)\n            assert document["region"] == event.identity.region\n            assert int(document["origin_generation"]) == event.identity.generation\n            assert int(document["origin_sequence"]) == event.identity.origin_sequence\n            assert str(document["payload_sha256"]).lower() == event.payload_sha256\n            expected_headers = {\n                "Nats-Msg-Id": event.identity.event_id,\n                "X-Event-Id": event.identity.event_id,\n                "X-Origin-Region": event.identity.region,\n                "X-Origin-Generation": str(event.identity.generation),\n                "X-Origin-Sequence": str(event.identity.origin_sequence),\n                "X-Payload-SHA256": event.payload_sha256,\n            }\n            for key, value in expected_headers.items():\n                assert message.headers.get(key) == value\n        assert observed == expected_replay_ids\n    finally:\n        manager.stop_one("west")\n')

replace_node(tests, 'test_f2p_generation_regression_is_held', 'def test_f2p_generation_regression_is_held(engine: ContinuityEngine) -> None:\n    """A lower origin sequence is held even when the stream fingerprint is unchanged."""\n    current = engine.store.confirmed_generation("west")\n    assert current is not None\n    observation = OriginObservation(\n        region="west",\n        stream_name=str(engine.region_config("west")["stream_name"]),\n        domain=str(engine.region_config("west")["domain"]),\n        stream_fingerprint=current.stream_fingerprint,\n        first_sequence=1,\n        last_sequence=42,\n        observed_at=datetime(2026, 8, 9, 1, 0, tzinfo=UTC),\n    )\n    result = engine.validate_origin_observation(observation)\n    assert result.generation == current.generation + 1\n    assert result.status is GenerationStatus.PENDING_APPROVAL\n    still_current = engine.store.confirmed_generation("west")\n    assert still_current is not None\n    assert still_current.generation == current.generation\n    assert still_current.last_observed_sequence == current.last_observed_sequence\n')

replace_node(tests, 'test_f2p_archive_metadata_preserves_origin_identity', 'def test_f2p_archive_metadata_preserves_origin_identity(\n    engine: ContinuityEngine,\n) -> None:\n    """Every documented archive-origin metadata dimension can independently block convergence."""\n    complete_archive(engine, "east")\n    domain_event = sample_event(engine, sequence=120)\n    checksum_event = sample_event(engine, sequence=121)\n    stream_event = sample_event(engine, sequence=122)\n    sequence_event = sample_event(engine, sequence=123)\n    engine.store.execute(\n        "UPDATE archive_index SET source_domain=\'edge-west\' WHERE event_id=?",\n        (domain_event.identity.event_id,),\n    )\n    engine.store.execute(\n        "UPDATE archive_index SET payload_sha256=? WHERE event_id=?",\n        ("0" * 64, checksum_event.identity.event_id),\n    )\n    engine.store.execute(\n        "UPDATE archive_index SET source_stream=\'WRONG_EDGE_STREAM\' WHERE event_id=?",\n        (stream_event.identity.event_id,),\n    )\n    engine.store.execute(\n        "UPDATE archive_index SET origin_sequence=7000 WHERE event_id=?",\n        (sequence_event.identity.event_id,),\n    )\n\n    summary = engine.reconcile_region("east", 1)\n    assert summary.converged is False\n    blocking_ids = {\n        finding.event_id\n        for finding in summary.blocking_findings\n        if finding.event_id is not None\n    }\n    assert {\n        domain_event.identity.event_id,\n        checksum_event.identity.event_id,\n        stream_event.identity.event_id,\n        sequence_event.identity.event_id,\n    } <= blocking_ids\n')

replace_node(tests, 'test_f2p_checkpoint_does_not_advance_before_effect_commit', 'def test_f2p_checkpoint_does_not_advance_before_effect_commit(\n    engine: ContinuityEngine,\n    monkeypatch: pytest.MonkeyPatch,\n) -> None:\n    """A failed effect commit cannot advance application state or acknowledge the delivery."""\n    event = sample_event(engine, sequence=5698)\n    engine.store.execute(\n        "DELETE FROM processing_effects WHERE consumer_name=\'telemetry-indexer\' AND event_id=?",\n        (event.identity.event_id,),\n    )\n    before = engine.store.checkpoint("telemetry-indexer", "east", 1)\n    assert before is not None\n    delivery = FakeDelivery(event, delivery_count=1)\n\n    def fail_commit(*args: Any, **kwargs: Any) -> Any:\n        raise RuntimeError("simulated effect store failure")\n\n    monkeypatch.setattr(engine.store, "commit_effect", fail_commit)\n    with pytest.raises(RuntimeError):\n        asyncio.run(\n            engine.process_delivery(\n                delivery,\n                worker_id="fault-worker",\n                fence_epoch=1,\n            )\n        )\n    after = engine.store.checkpoint("telemetry-indexer", "east", 1)\n    assert after is not None\n    assert after.last_effect_sequence == before.last_effect_sequence\n    assert after.last_ack_sequence == before.last_ack_sequence\n    assert delivery.ack_calls == 0\n')

replace_node(tests, 'test_f2p_poison_event_is_quarantined_without_completion', 'def test_f2p_poison_event_is_quarantined_without_completion(\n    engine: ContinuityEngine,\n) -> None:\n    """Quarantine persists audit evidence without completed business effect or progress."""\n    event = sample_event(engine, sequence=5680)\n    consumer = "safety-state-projector"\n    engine.store.execute(\n        "DELETE FROM poison_events WHERE consumer_name=? AND event_id=?",\n        (consumer, event.identity.event_id),\n    )\n    engine.store.execute(\n        "DELETE FROM processing_effects WHERE consumer_name=? AND event_id=?",\n        (consumer, event.identity.event_id),\n    )\n    engine.store.execute(\n        "DELETE FROM effect_dispatches WHERE consumer_name=? AND event_id=?",\n        (consumer, event.identity.event_id),\n    )\n    before = engine.store.checkpoint(consumer, "east", 1)\n    assert before is not None\n    asyncio.run(\n        engine.process_delivery(\n            FakeDelivery(event, consumer_name=consumer, delivery_count=5),\n            worker_id="safety-worker",\n            fence_epoch=1,\n            poison_predicate=lambda _: True,\n        )\n    )\n    after = engine.store.checkpoint(consumer, "east", 1)\n    effect = engine.store.effect(consumer, event.identity.event_id)\n    poison = engine.store.execute(\n        "SELECT disposition,delivery_count FROM poison_events WHERE consumer_name=? AND event_id=?",\n        (consumer, event.identity.event_id),\n    ).fetchone()\n    assert after is not None\n    assert poison is not None\n    assert poison["disposition"] == "QUARANTINED"\n    assert int(poison["delivery_count"]) >= 5\n    assert dispatch_count(engine, consumer, event.identity.event_id) == 0\n    if effect is not None:\n        assert effect.status is not EffectStatus.COMMITTED\n    assert after.last_effect_sequence == before.last_effect_sequence\n    assert after.last_ack_sequence == before.last_ack_sequence\n')

replace_node(tests, 'test_f2p_restart_detects_ack_floor_effect_ledger_gap', 'def test_f2p_restart_detects_ack_floor_effect_ledger_gap(\n    engine: ContinuityEngine, tmp_path: Path\n) -> None:\n    """Restart health compares live JetStream consumer progress with durable application state."""\n    runtime_root = tmp_path / "consumer-health-runtime"\n    nats_config_dir = runtime_root / "config/nats"\n    hub_store = runtime_root / "state/nats/hub"\n    nats_config_dir.mkdir(parents=True)\n    hub_store.mkdir(parents=True)\n    (nats_config_dir / "hub.conf").write_text(\n        "\\n".join(\n            (\n                "server_name: HUB-CONSUMER-HEALTH",\n                "port: 4222",\n                "http: 8222",\n                "jetstream {",\n                f\'  store_dir: "{hub_store}"\',\n                \'  domain: "hub"\',\n                "  max_mem_store: 67108864",\n                "  max_file_store: 268435456",\n                "}",\n                "",\n            )\n        ),\n        encoding="utf-8",\n    )\n    set_checkpoint(\n        engine, "telemetry-indexer", "east", effect=0, ack=0, js_floor=0\n    )\n    event = sample_event(engine, region="east", sequence=5650)\n    manager = LabProcessManager(runtime_root)\n    manager.start_one("hub")\n    try:\n        manager.wait_monitor("http://127.0.0.1:8222", timeout=10)\n\n        async def create_external_progress() -> int:\n            pool = NatsConnectionPool()\n            try:\n                endpoints = endpoints_from_engine(engine)\n                admin = JetStreamAdmin(pool, endpoints)\n                stream_name = engine.topology().hub_archive.name\n                await admin.upsert_stream(\n                    "hub",\n                    stream_name,\n                    {\n                        "subjects": ["continuity.health.east"],\n                        "retention": "limits",\n                        "storage": "file",\n                        "num_replicas": 1,\n                        "duplicate_window": 120 * 1_000_000_000,\n                        "max_age": 259200 * 1_000_000_000,\n                        "allow_direct": False,\n                        "deny_delete": True,\n                        "deny_purge": True,\n                    },\n                )\n                await admin.upsert_consumer(\n                    "hub",\n                    stream_name,\n                    "telemetry-indexer",\n                    filter_subject="continuity.health.east",\n                    ack_wait_seconds=30,\n                    max_ack_pending=32,\n                )\n                endpoint = endpoints["hub"]\n                client = await pool.get(endpoint)\n                js = client.jetstream(domain=endpoint.domain)\n                await js.publish("continuity.health.east", event.wire_payload())\n                subscription = await js.pull_subscribe(\n                    subject="continuity.health.east",\n                    durable="telemetry-indexer",\n                    stream=stream_name,\n                )\n                messages = await subscription.fetch(batch=1, timeout=2)\n                assert len(messages) == 1\n                await messages[0].ack()\n                await client.flush()\n                for _ in range(40):\n                    info = await admin.consumer_info(\n                        "hub", stream_name, "telemetry-indexer"\n                    )\n                    if info.ack_floor_stream_sequence > 0:\n                        return info.ack_floor_stream_sequence\n                    await asyncio.sleep(0.05)\n                return 0\n            finally:\n                await pool.close()\n\n        external_ack_floor = asyncio.run(create_external_progress())\n        assert external_ack_floor > 0\n        persisted = engine.store.checkpoint("telemetry-indexer", "east", 1)\n        assert persisted is not None and persisted.is_consistent\n        assert persisted.application_sequence == 0\n\n        report = engine.inspect_health()\n        assert report.consumers_ok is False\n    finally:\n        manager.stop_one("hub")\n')

replace_node(tests, 'test_f2p_replay_plan_contains_only_missing_events', 'def test_f2p_replay_plan_contains_only_missing_events(engine: ContinuityEngine) -> None:\n    """Replay execution uses current archive membership, not stale replay-item completion state."""\n    complete_archive(engine, "east")\n    first_missing = {"evt-east-g01-005800", "evt-east-g01-005801"}\n    for event_id in first_missing:\n        engine.store.execute("DELETE FROM archive_index WHERE event_id=?", (event_id,))\n\n    first = engine.plan_replay(\n        region="east",\n        generation=1,\n        created_by="verifier",\n        reason="first isolated reconciliation gap",\n        approve=True,\n        approved_by="shift-lead",\n    )\n    assert first.plan is not None\n    assert set(first.plan.event_ids) == first_missing\n    assert set(first.missing_event_ids) == first_missing\n    assert first.plan.replay_range == ReplayRange("east", 1, 5800, 5801)\n\n    resume_id = "evt-east-g01-005800"\n    late_archive_id = "evt-east-g01-005801"\n    engine.store.update_replay_item(\n        first.plan.plan_id,\n        resume_id,\n        state="PUBLISHED",\n        increment_attempt=True,\n    )\n    late_event = engine.store.event_by_id(late_archive_id)\n    assert late_event is not None\n    engine.store.execute(\n        "INSERT INTO archive_index(event_id,region,generation,origin_sequence,hub_stream_sequence,payload_sha256,archived_at,source_stream,source_domain,duplicate_observation_count) "\n        "VALUES(?,?,?,?,?,?,?,?,?,0)",\n        (\n            late_event.identity.event_id,\n            late_event.identity.region,\n            late_event.identity.generation,\n            late_event.identity.origin_sequence,\n            900_000 + late_event.identity.origin_sequence,\n            late_event.payload_sha256,\n            "2026-08-09T02:00:00Z",\n            str(engine.store.region("east")["physical_stream"]),\n            str(engine.store.region("east")["jetstream_domain"]),\n        ),\n    )\n\n    lease = engine.acquire_recovery_lease(\n        region="east",\n        owner_id="resume-authority-worker",\n        ttl_seconds=300,\n        at=datetime.now(UTC),\n    )\n    publisher = RecordingPublisher(engine.store)\n    outcome = asyncio.run(\n        engine.execute_replay_plan(\n            first.plan.plan_id,\n            owner_id="resume-authority-worker",\n            fence_epoch=lease.fence_epoch,\n            publisher=publisher,\n        )\n    )\n    assert outcome.completed is True\n    assert [call["event_id"] for call in publisher.calls] == [resume_id]\n    first_items = {\n        item.event_id: item.state\n        for item in engine.store.replay_items(first.plan.plan_id)\n    }\n    assert first_items[resume_id] == "PUBLISHED"\n    assert first_items[late_archive_id] == "ALREADY_ARCHIVED"\n\n    complete_archive(engine, "east")\n    second_missing = {"evt-east-g01-005900", "evt-east-g01-005901"}\n    for event_id in second_missing:\n        engine.store.execute("DELETE FROM archive_index WHERE event_id=?", (event_id,))\n\n    second = engine.plan_replay(\n        region="east",\n        generation=1,\n        created_by="verifier",\n        reason="second disjoint reconciliation gap",\n        approve=True,\n        approved_by="shift-lead",\n    )\n    assert second.plan is not None\n    assert set(second.plan.event_ids) == second_missing\n    assert set(second.missing_event_ids) == second_missing\n    assert first.plan.replay_range.overlaps(second.plan.replay_range) is False\n')

replace_node(tests, 'test_f2p_cleanup_stops_at_archive_watermark', 'def test_f2p_cleanup_stops_at_archive_watermark(engine: ContinuityEngine) -> None:\n    """Cleanup-safe sequence equals the archive floor when archive is the unique minimum."""\n    archive_sequences = [\n        record.identity.origin_sequence\n        for record in engine.store.iter_archive(region="east", generation=1)\n    ]\n    expected_floor = contiguous_floor(archive_sequences)\n    slowest = engine.store.slowest_required_consumer_sequence("east", 1)\n    assert expected_floor < slowest\n    assert engine.store.first_active_replay_sequence("east", 1) is None\n    decision = engine.compute_retention_decision(region="east", generation=1)\n    assert decision.archive_sequence == expected_floor\n    assert decision.safe_sequence == expected_floor\n')

replace_node(tests, 'test_f2p_cleanup_stops_at_slowest_required_consumer', 'def test_f2p_cleanup_stops_at_slowest_required_consumer(\n    engine: ContinuityEngine,\n) -> None:\n    """Cleanup-safe sequence equals the slowest required consumer when it is the minimum."""\n    complete_archive(engine, "east")\n    required = engine.store.required_consumers()\n    assert len(required) >= 2\n    set_checkpoint(engine, required[0], "east", effect=4200)\n    for consumer in required[1:]:\n        set_checkpoint(engine, consumer, "east", effect=6000)\n    assert engine.store.first_active_replay_sequence("east", 1) is None\n\n    decision = engine.compute_retention_decision(region="east", generation=1)\n    assert decision.archive_sequence == 6000\n    assert decision.required_consumer_sequence == 4200\n    assert decision.safe_sequence == 4200\n')

replace_node(tests, 'test_f2p_cleanup_preserves_rows_for_active_replay_plan', 'def test_f2p_cleanup_preserves_rows_for_active_replay_plan(\n    engine: ContinuityEngine,\n) -> None:\n    """Cleanup-safe sequence equals replay pin minus one when the active plan is the minimum."""\n    complete_archive(engine, "west")\n    for consumer in engine.store.required_consumers():\n        set_checkpoint(engine, consumer, "west", effect=6000)\n    decision = engine.compute_retention_decision(region="west", generation=1)\n    assert decision.archive_sequence == 6000\n    assert decision.required_consumer_sequence == 6000\n    assert decision.replay_pin_sequence == 5311\n    assert decision.safe_sequence == 5310\n')

replace_node(tests, 'test_f2p_retention_policy_covers_recovery_horizon', 'def test_f2p_retention_policy_covers_recovery_horizon(engine: ContinuityEngine) -> None:\n    """JetStream and durable journal retention enforce the exact recovery-horizon boundary."""\n    policy = engine.retention_policy("east")\n    assert (\n        engine.edge_stream_policy("east").max_age_seconds\n        >= policy.required_horizon_seconds\n    )\n    assert (\n        engine.edge_stream_policy("west").max_age_seconds\n        >= policy.required_horizon_seconds\n    )\n    assert engine.hub_stream_policy().max_age_seconds >= policy.required_horizon_seconds\n\n    complete_archive(engine, "east")\n    for consumer in engine.store.required_consumers():\n        set_checkpoint(engine, consumer, "east", effect=6000)\n\n    at = datetime(2026, 8, 12, 12, 0, tzinfo=UTC)\n    within_horizon = "evt-east-g01-000100"\n    beyond_horizon = "evt-east-g01-000101"\n    engine.store.execute(\n        "UPDATE event_journal SET retention_hold=0,accepted_at=? WHERE event_id=?",\n        (\n            (at - timedelta(seconds=policy.required_horizon_seconds - 1)).isoformat(),\n            within_horizon,\n        ),\n    )\n    engine.store.execute(\n        "UPDATE event_journal SET retention_hold=0,accepted_at=? WHERE event_id=?",\n        (\n            (at - timedelta(seconds=policy.required_horizon_seconds + 1)).isoformat(),\n            beyond_horizon,\n        ),\n    )\n\n    decision = engine.compute_retention_decision(\n        region="east",\n        generation=1,\n        at=at,\n        limit=6000,\n    )\n    candidates = set(decision.eligible_event_ids)\n    assert within_horizon not in candidates\n    assert beyond_horizon in candidates\n')

replace_node(coverage, 'test_f2p_final_health_and_reconciliation_reports_are_materialized', 'def test_f2p_final_health_and_reconciliation_reports_are_materialized(\n    tmp_path: Path,\n) -> None:\n    """Verify emits contract-defined truthful reports and preserves captured incident evidence."""\n    runtime_root = _operator_root(tmp_path)\n    completed = subprocess.run(\n        [\n            str(ROOT / "bin/continuityctl"),\n            "verify",\n            "--root",\n            str(runtime_root),\n            "--compact",\n        ],\n        check=False,\n        capture_output=True,\n        text=True,\n        timeout=45,\n    )\n    assert completed.returncode in {0, 2}, completed.stderr\n\n    health_path = runtime_root / "out/health.json"\n    reconciliation_path = runtime_root / "out/reconciliation.json"\n    assert health_path.is_file()\n    assert reconciliation_path.is_file()\n    health = json.loads(health_path.read_text(encoding="utf-8"))\n    reconciliation = json.loads(reconciliation_path.read_text(encoding="utf-8"))\n\n    for report in (health, reconciliation):\n        assert "generated_at" in report\n        timestamp = report["generated_at"]\n        assert isinstance(timestamp, (str, int, float))\n        if isinstance(timestamp, str):\n            assert timestamp.strip()\n\n    subsystem_fields = (\n        "topology_ok",\n        "generations_ok",\n        "publication_ok",\n        "archive_ok",\n        "consumers_ok",\n        "retention_ok",\n        "recovery_ok",\n    )\n    for field in subsystem_fields:\n        assert isinstance(health[field], bool)\n    assert isinstance(health["healthy"], bool)\n    assert health["healthy"] is all(health[field] for field in subsystem_fields)\n\n    def contiguous_floor(values: list[int]) -> int:\n        present = set(values)\n        floor = 0\n        while floor + 1 in present:\n            floor += 1\n        return floor\n\n    connection = sqlite3.connect(runtime_root / "state/continuity.db")\n    connection.row_factory = sqlite3.Row\n    try:\n        required_consumers = [\n            str(row["consumer_name"])\n            for row in connection.execute(\n                "SELECT consumer_name FROM consumer_registry "\n                "WHERE required=1 AND enabled=1 ORDER BY consumer_name"\n            ).fetchall()\n        ]\n        active_plans = int(\n            connection.execute(\n                "SELECT COUNT(*) FROM replay_plans "\n                "WHERE status IN (\'APPROVED\',\'RUNNING\')"\n            ).fetchone()[0]\n        )\n        expected_region_convergence: dict[str, bool] = {}\n\n        assert set(reconciliation["regions"]) == {"east", "west"}\n        for region in ("east", "west"):\n            confirmed = connection.execute(\n                "SELECT generation,last_observed_sequence FROM origin_generations "\n                "WHERE region=? AND status=\'CONFIRMED\' ORDER BY generation",\n                (region,),\n            ).fetchall()\n            assert confirmed, f"{region} must retain a confirmed generation"\n            generation = int(confirmed[-1]["generation"])\n            confirmed_watermark = int(confirmed[-1]["last_observed_sequence"])\n            region_row = connection.execute(\n                "SELECT physical_stream,jetstream_domain FROM regions WHERE region=?",\n                (region,),\n            ).fetchone()\n            assert region_row is not None\n            expected_stream = str(region_row["physical_stream"])\n            expected_domain = str(region_row["jetstream_domain"])\n\n            journal_rows = connection.execute(\n                "SELECT event_id,origin_sequence,payload_sha256 FROM event_journal "\n                "WHERE region=? AND generation=?",\n                (region, generation),\n            ).fetchall()\n            archive_rows = connection.execute(\n                "SELECT event_id,origin_sequence,payload_sha256,source_stream,source_domain,"\n                "duplicate_observation_count FROM archive_index "\n                "WHERE region=? AND generation=?",\n                (region, generation),\n            ).fetchall()\n            journal = {\n                str(row["event_id"]): (\n                    int(row["origin_sequence"]),\n                    str(row["payload_sha256"]).lower(),\n                )\n                for row in journal_rows\n            }\n            archive = {\n                str(row["event_id"]): (\n                    int(row["origin_sequence"]),\n                    str(row["payload_sha256"]).lower(),\n                    str(row["source_stream"]),\n                    str(row["source_domain"]),\n                )\n                for row in archive_rows\n            }\n            missing_ids = set(journal) - set(archive)\n            unexpected_ids = set(archive) - set(journal)\n            has_metadata_mismatch = any(\n                journal[event_id][0] != archive[event_id][0]\n                or journal[event_id][1] != archive[event_id][1]\n                or archive[event_id][2] != expected_stream\n                or archive[event_id][3] != expected_domain\n                for event_id in set(journal) & set(archive)\n            )\n            archive_floor = contiguous_floor(\n                [value[0] for value in archive.values()]\n            )\n\n            progress: dict[str, int] = {}\n            for consumer_name in required_consumers:\n                checkpoint = connection.execute(\n                    "SELECT last_effect_sequence,last_ack_sequence "\n                    "FROM consumer_checkpoints "\n                    "WHERE consumer_name=? AND region=? AND generation=?",\n                    (consumer_name, region, generation),\n                ).fetchone()\n                if checkpoint is None:\n                    progress[consumer_name] = 0\n                    continue\n                progress[consumer_name] = min(\n                    int(checkpoint["last_effect_sequence"]),\n                    int(checkpoint["last_ack_sequence"]),\n                )\n\n            consumer_lag_count = sum(\n                1\n                for sequence in progress.values()\n                if sequence < confirmed_watermark\n            )\n            expected_converged = (\n                archive_floor >= confirmed_watermark\n                and not missing_ids\n                and not unexpected_ids\n                and not has_metadata_mismatch\n                and consumer_lag_count == 0\n            )\n            expected_region_convergence[region] = expected_converged\n\n            actual = reconciliation["regions"][region]\n            assert actual["status"] == (\n                "CONVERGED" if expected_converged else "DIVERGED"\n            )\n            assert actual["journal_event_count"] == len(journal)\n            assert actual["archive_event_count"] == len(archive)\n            assert actual["missing_count"] == len(missing_ids)\n            assert actual["unexpected_count"] == len(unexpected_ids)\n            assert isinstance(actual["duplicate_count"], int)\n            assert actual["duplicate_count"] >= 0\n            assert isinstance(actual["metadata_mismatch_count"], int)\n            assert actual["metadata_mismatch_count"] >= 0\n            assert actual["consumer_lag_count"] == consumer_lag_count\n            assert (\n                actual["highest_contiguous_archive_origin_sequence"]\n                == archive_floor\n            )\n            assert actual["required_consumer_progress"] == progress\n            assert actual["converged"] is expected_converged\n\n        assert reconciliation["converged"] is all(\n            expected_region_convergence.values()\n        )\n        assert (\n            connection.execute("SELECT COUNT(*) FROM event_journal").fetchone()[0]\n            == 12000\n        )\n        assert (\n            connection.execute(\n                "SELECT COUNT(*) FROM consumer_checkpoints"\n            ).fetchone()[0]\n            >= 4\n        )\n        assert active_plans >= 1\n    finally:\n        connection.close()\n\n    captured_incident_digests = {\n        ROOT / "ops/stream-state.json": "763397e13b62c237dc37a0d1601a438e9a9247a681aaacb625f8f3425b154b1c",\n        ROOT / "ops/shift-handoff.txt": "4a1b66e39bff8de9db528a0927fb37017a060aba4994c25939a0225fa8361be0",\n        ROOT / "log/archive/inc-2026-0808-17-controller.log": "fc5a85713d9b963e18b7550048a11de16349c9daa260623f72aa33e6862fb7d6",\n    }\n    for captured_path, expected_digest in captured_incident_digests.items():\n        assert captured_path.is_file()\n        assert hashlib.sha256(captured_path.read_bytes()).hexdigest() == expected_digest\n')

